import{_ as l,D as s,o as t,c as n,j as a,a as e,I as i,w as d,am as r}from"./chunks/framework.DXw8qDd0.js";const C=JSON.parse('{"title":"Codex的Goal指令如何用","description":"","frontmatter":{"title":"Codex的Goal指令如何用","time":"2026-06-07T00:00:00.000Z","tags":["codex"]},"headers":[],"relativePath":"笔记/Codex/Codex的Goal指令如何用.md","filePath":"笔记/Codex/Codex的Goal指令如何用.md"}'),p={name:"笔记/Codex/Codex的Goal指令如何用.md"},c=r(`<h1 id="codex-的-goal-指令如何用" tabindex="-1">Codex 的 Goal 指令如何用 <a class="header-anchor" href="#codex-的-goal-指令如何用" aria-label="Permalink to &quot;Codex 的 Goal 指令如何用&quot;">​</a></h1><hr><h2 id="什么是-goal" tabindex="-1">什么是 Goal <a class="header-anchor" href="#什么是-goal" aria-label="Permalink to &quot;什么是 Goal&quot;">​</a></h2><p>Goal 是 Codex CLI 和桌面 App 中的一个斜杠命令（/goal），用来为当前对话设置一个明确的目标。</p><p>它本质上是一个「任务追踪器」——你告诉 Codex 你想达成什么，Codex 会在完成时标记目标为 complete，并汇报 token 使用量和耗时。</p><hr><h2 id="如何使用" tabindex="-1">如何使用 <a class="header-anchor" href="#如何使用" aria-label="Permalink to &quot;如何使用&quot;">​</a></h2><h3 id="设置目标" tabindex="-1">设置目标 <a class="header-anchor" href="#设置目标" aria-label="Permalink to &quot;设置目标&quot;">​</a></h3><p>在对话输入框中输入：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span>/goal 把这个项目的 README 翻译成中文</span></span></code></pre></div><p>或者直接在对话中说：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span>请创建一个 goal：重构认证模块</span></span></code></pre></div><h3 id="查看当前目标" tabindex="-1">查看当前目标 <a class="header-anchor" href="#查看当前目标" aria-label="Permalink to &quot;查看当前目标&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span>/goal</span></span></code></pre></div><p>不带参数时会显示当前目标的状态、token 预算和使用情况。</p><h3 id="目标完成" tabindex="-1">目标完成 <a class="header-anchor" href="#目标完成" aria-label="Permalink to &quot;目标完成&quot;">​</a></h3><p>当任务完成后，Codex 会自动将目标标记为 complete，并报告：</p><ul><li>使用了多少 token</li><li>花了多少时间</li></ul><hr><h2 id="适用场景" tabindex="-1">适用场景 <a class="header-anchor" href="#适用场景" aria-label="Permalink to &quot;适用场景&quot;">​</a></h2><ol><li><strong>长任务追踪</strong>：当一个任务需要多轮对话才能完成时，Goal 帮你追踪进度。</li><li><strong>Token 预算管理</strong>：可以给 Goal 设置 token 上限，防止消耗过多。</li><li><strong>任务复盘</strong>：完成后可以看到 token 用量和耗时，帮助评估效率。</li></ol><hr><h2 id="常见用法示例" tabindex="-1">常见用法示例 <a class="header-anchor" href="#常见用法示例" aria-label="Permalink to &quot;常见用法示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span>/goal 修复登录模块的所有单元测试</span></span>
<span class="line"><span>/goal 编写项目的 AGENTS.md</span></span>
<span class="line"><span>/goal 将 10 个 API 端点添加错误处理</span></span>
<span class="line"><span>/goal 分析这个仓库的架构并输出学习路线</span></span></code></pre></div><hr><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>/goal 用来设置和追踪当前对话的任务目标。</li><li>支持设置 token 预算，完成后自动汇报用量。</li><li>适合长任务、复杂任务的进度管理和复盘。</li></ul><hr>`,28);function h(u,g,b,x,_,k){const o=s("VPNolebaseInlineLinkPreview");return t(),n("div",null,[c,a("blockquote",null,[a("p",null,[e("📎 "),i(o,{href:"/ocdsync/笔记/"},{default:d(()=>[e("📒 返回笔记索引")]),_:1})])])])}const v=l(p,[["render",h]]);export{C as __pageData,v as default};
